import type { Browser } from 'playwright';
import type {
  AuditManifest,
  AuditManualFields,
  AnalysisSiteContext,
  Finding,
  FindingsDelta,
  FindingsProvenance,
  GradeOverride,
  LlmOutput,
  ObligationAssessment,
  PreparationPreviewLanguage,
  ReportLanguage,
} from '@odysseus/core';

/**
 * The analysis as generated by @odysseus/llm plus the provenance fields
 * analyze.ts writes alongside it to analyses/<timestamp>-<lang>.json.
 * generatedAt is typed as Date, not the ISO string the JSON file actually
 * stores, matching the same disk-vs-memory convention already used for
 * Finding.firstSeenAt/lastSeenAt: parsing the string is the caller's job
 * at the boundary, not this package's.
 */
export interface StoredAnalysis extends LlmOutput {
  /** Absent only on legacy artifacts, which report generation rejects. */
  analysisId?: string;
  auditId: string;
  /** Absent only on legacy artifacts, which report generation rejects. */
  findingsProvenance?: FindingsProvenance;
  language: ReportLanguage;
  model: string;
  temperature: number;
  generatedAt: Date;
  /** Computed once per audit by @odysseus/core's assessObligations and
   *  identical across every language's StoredAnalysis for that audit -
   *  the determination itself is language-neutral, only its report
   *  rendering (packages/report/src/template) varies by language.
   *  Optional: analyses generated before this milestone predate it. */
  obligationAssessment?: ObligationAssessment;
  /** The exact intake or catalogue facts shown to the writing pass. Optional
   * for analyses created before writing-context provenance was recorded. */
  siteContext?: AnalysisSiteContext;
  /** Present only on analyses produced by the audit fallback gate
   *  (docs/rules/llm-layer-rules.md section 10): the structure and
   *  writing passes never ran for this document. Absent on every
   *  model-generated analysis, including all legacy artifacts. */
  generationMode?: 'static-fallback';
}

export interface VerifiedStoredAnalysis extends StoredAnalysis {
  analysisId: string;
  findingsProvenance: FindingsProvenance;
}

export interface ReportRenderMetadata {
  reportId: string;
  renderedAt: Date;
  rendererBuild: string;
  templateVersion: number;
}

/** Milestone 8 introduced a paid screening tier alongside the full audit,
 *  both rendered from the same findings.json with tier only affecting
 *  report depth. Dropped 2026-08-16 (docs/rules/offer-positioning.md): the
 *  commercial model is now single-tier, the full audit is the only paid
 *  deliverable, so there is no longer a tier to select at generation
 *  time. The free, pre-purchase outreach preview introduced the same day
 *  (docs/rules/outreach-rules.md) is a deliberately separate document kind,
 *  not a smaller tier of this one - see generateOutreachPreviewHtml. It
 *  produces HTML, never a PDF: nothing about it launches Chromium. */
export interface GenerateReportInput {
  /** Created before rendering and reused by every report artifact. */
  renderMetadata: ReportRenderMetadata;
  /** Used to resolve page screenshot files on disk (manifest.pages[].pageDir
   *  is relative to this directory). Never read for anything else: findings
   *  and the manifest itself are passed in already parsed, not re-read here. */
  auditDir: string;
  manifest: AuditManifest;
  /** Unfiltered: the full findings.json, not the LLM-filtered set, since
   *  the appendix must include minor findings the model never saw. */
  findings: Finding[];
  analysis: StoredAnalysis;
  /** Manual-input-layer milestone: operator-supplied pre-report
   *  enrichment, read fresh from the store at render time (not baked
   *  into `analysis`, which is regenerated far less often - see
   *  packages/interface's report-stage.ts). Absent entirely for an audit
   *  with no saved manual fields; every consuming section must render
   *  its existing fallback in that case (rule 5). */
  manualFields?: AuditManualFields;
  /** Plan 019: the bounded preparation preview for THIS analysis's
   *  language, resolved by the orchestration layer (never queried or
   *  derived here). Contains only render-ready strings and typed states;
   *  absent means the report renders its safe generic fallbacks
   *  unchanged. */
  preparation?: PreparationPreviewLanguage;
  /** Issue: operator-reviewed overall grade override, read fresh from the
   *  store at render time (not baked into `analysis`) - same convention as
   *  manualFields above. Absent means the report renders the automatic
   *  grade unchanged. */
  gradeOverride?: GradeOverride;
  /** Plan 051: the re-audit findings delta against the most recent
   *  delivered audit of the same site, computed by the orchestration layer
   *  with @odysseus/core's computeFindingsDelta and passed in, never derived
   *  here from a second findings file. Absent on every report without a
   *  delivered baseline, which renders unchanged. */
  delta?: FindingsDelta;
  /** Issue #6: a caller generating both language reports for the same
   *  audit back to back (packages/interface's report-stage.ts) launches
   *  Chromium once and passes it here for both passes, instead of paying a
   *  fresh browser launch per language. generateReportPdf launches and
   *  closes its own browser when this is absent, unchanged from before. */
  browser?: Browser;
}
